import java.util.Scanner;

public class Main {
    static final int MAX = 510;
    static int total_n, total_m, modulus;
    static int[][] C = new int[MAX][MAX];
    static Pair[][] dp_table = new Pair[MAX][MAX];

    static class Pair {
        int fi, se;

        Pair(int fi, int se) {
            this.fi = fi;
            this.se = se;
        }

        Pair add(Pair b) {
            return new Pair(add_mod(this.fi, b.fi), add_mod(this.se, b.se));
        }

        Pair multiply(Pair b) {
            long fi_part = ((long) this.fi * b.fi) % modulus;
            long se_part = ((long) this.fi * b.se + (long) this.se * b.fi) % modulus;
            return new Pair((int) fi_part, (int) se_part);
        }
    }

    static int add_mod(int a, int b) {
        int res = a + b;
        if (res >= modulus) res -= modulus;
        return res;
    }

    static int sum_range(int left, int right) {
        return (left + right) * (right - left + 1) / 2;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        total_n = sc.nextInt();
        total_m = sc.nextInt();
        modulus = sc.nextInt();

        for (int i = 0; i < MAX; i++) {
            C[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                C[i][j] = add_mod(C[i - 1][j], C[i - 1][j - 1]);
            }
        }

        for (int i = 0; i <= total_n; i++) {
            for (int j = 0; j <= total_m; j++) {
                dp_table[i][j] = new Pair(0, 0);
            }
        }

        for (int i = 0; i <= total_n; i++) {
            dp_table[i][0] = new Pair(1, 0);
            for (int j = 1; j <= i && j <= total_m; j++) {
                if (i != j) {
                    for (int k = 1; k <= i; k++) {
                        Pair term = dp_table[k - 1][k - 1].multiply(dp_table[i - k][j - k + 1])
                                .multiply(new Pair(C[j][k - 1], 0));
                        dp_table[i][j] = dp_table[i][j].add(term);
                    }
                } else {
                    for (int k = 1; k <= i; k++) {
                        Pair term1 = dp_table[k - 1][k - 1];
                        Pair term2 = dp_table[i - k][i - k];
                        Pair comb = new Pair(C[i - 1][k - 1], 0);
                        int factor = i + 1 - sum_range(1, k) + sum_range(k + 1, i) - k * (i - k);
                        Pair factor_pair = new Pair(factor, 0);
                        Pair term = term1.multiply(term2).multiply(comb).multiply(factor_pair);
                        dp_table[i][j] = dp_table[i][j].add(term);
                    }
                }
            }
        }

        System.out.println(dp_table[total_n][total_m].se);
        sc.close();
    }
}
